"use client";

import React, { useEffect, useRef, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { motion, useReducedMotion } from "framer-motion";

// Configurable animation speed (seconds for one full 6-category loop)
export const SLIDER_DURATION = 36;

export interface WorkspaceCategory {
  id: string;
  title: string;
  subtitle: string;
  topImage: string;
  bottomImage: string;
}

export const WORKSPACE_CATEGORIES: WorkspaceCategory[] = [
  {
    id: "not-desk",
    title: "NOT DESK",
    subtitle: "Pick your way",
    topImage: "/assets/slider/not-desk-top.png",
    bottomImage: "/assets/slider/not-desk-bottom.png",
  },
  {
    id: "dedicated-desk",
    title: "DEDICATED DESK",
    subtitle: "Focus. Every day.",
    topImage: "/assets/slider/dedicated-desk-top.png",
    bottomImage: "/assets/slider/dedicated-desk-bottom.png",
  },
  {
    id: "private-cabin",
    title: "PRIVATE CABIN",
    subtitle: "Your space. Your rules.",
    topImage: "/assets/slider/private-cabin-top.png",
    bottomImage: "/assets/slider/private-cabin-bottom.png",
  },
  {
    id: "meeting-room",
    title: "MEETING ROOM",
    subtitle: "Collaborate better",
    topImage: "/assets/slider/meeting-room-top.png",
    bottomImage: "/assets/slider/meeting-room-bottom.png",
  },
  {
    id: "event-space",
    title: "EVENT SPACE",
    subtitle: "For bigger ideas",
    topImage: "/assets/slider/event-space-top.png",
    bottomImage: "/assets/slider/event-space-bottom.png",
  },
  {
    id: "community",
    title: "COMMUNITY",
    subtitle: "More than work",
    topImage: "/assets/slider/community-top.png",
    bottomImage: "/assets/slider/community-bottom.png",
  },
];

// Repeat sequence 4 times for seamless continuous marquee
const REPEATED_ITEMS = [
  ...WORKSPACE_CATEGORIES,
  ...WORKSPACE_CATEGORIES,
  ...WORKSPACE_CATEGORIES,
  ...WORKSPACE_CATEGORIES,
];

export default function WorkspaceSlider() {
  const shouldReduceMotion = useReducedMotion();
  const viewportRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const columnRefs = useRef<(HTMLDivElement | null)[]>([]);

  // Track the active item index currently closest to center phone
  const [activeItemKey, setActiveItemKey] = useState<string | null>(null);
  const activeKeyRef = useRef<string | null>(null);

  // Single loop measurement for true infinite reset
  const [singleLoopWidth, setSingleLoopWidth] = useState(0);

  // Measure the width of one complete 6-item set
  useEffect(() => {
    const measure = () => {
      if (columnRefs.current[0] && columnRefs.current[WORKSPACE_CATEGORIES.length]) {
        const firstCol = columnRefs.current[0];
        const seventhCol = columnRefs.current[WORKSPACE_CATEGORIES.length];
        if (firstCol && seventhCol) {
          const width = seventhCol.offsetLeft - firstCol.offsetLeft;
          if (width > 0) {
            setSingleLoopWidth(width);
          }
        }
      }
    };

    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, []);

  // Performance-conscious active-item detection (throttled check, only setState on change)
  useEffect(() => {
    if (shouldReduceMotion) return;

    let animationFrameId: number;
    let lastCheckTime = 0;

    const checkActiveColumn = (time: number) => {
      // Check every ~60ms (~16 times/sec) to conserve CPU
      if (time - lastCheckTime > 60 && viewportRef.current) {
        lastCheckTime = time;
        const viewportRect = viewportRef.current.getBoundingClientRect();
        const center = viewportRect.left + viewportRect.width / 2;

        let closestKey: string | null = null;
        let minDistance = Infinity;

        // Check each column's distance to center phone
        for (let i = 0; i < columnRefs.current.length; i++) {
          const colEl = columnRefs.current[i];
          if (!colEl) continue;

          const rect = colEl.getBoundingClientRect();
          const colCenter = rect.left + rect.width / 2;
          const dist = Math.abs(colCenter - center);

          // Active zone: within 75% of column width from center
          if (dist < minDistance && dist < rect.width * 0.85) {
            minDistance = dist;
            closestKey = `${REPEATED_ITEMS[i].id}-${i}`;
          }
        }

        // ONLY update React state if the active column actually changed
        if (closestKey !== activeKeyRef.current) {
          activeKeyRef.current = closestKey;
          setActiveItemKey(closestKey);
        }
      }

      animationFrameId = requestAnimationFrame(checkActiveColumn);
    };

    animationFrameId = requestAnimationFrame(checkActiveColumn);
    return () => cancelAnimationFrame(animationFrameId);
  }, [shouldReduceMotion]);

  return (
    <div className="relative mt-8 sm:mt-10 max-w-[1180px] mx-auto select-none">
      {/* Viewport container: hides overflow on left and right */}
      <div
        ref={viewportRef}
        className="relative w-full overflow-hidden pt-4 pb-12"
      >
        {/* ========================================================= */}
        {/* 1. LAYER: INFINITE MOVING IMAGE STRIP (BEHIND THE PHONE)  */}
        {/* ========================================================= */}
        <motion.div
          ref={trackRef}
          className="flex items-start will-change-transform"
          style={{ width: "max-content" }}
          animate={
            shouldReduceMotion || singleLoopWidth === 0
              ? { x: 0 }
              : { x: [0, -singleLoopWidth] }
          }
          transition={
            shouldReduceMotion || singleLoopWidth === 0
              ? { duration: 0 }
              : {
                  x: {
                    repeat: Infinity,
                    repeatType: "loop",
                    duration: SLIDER_DURATION,
                    ease: "linear",
                  },
                }
          }
        >
          {REPEATED_ITEMS.map((item, index) => {
            const uniqueKey = `${item.id}-${index}`;
            const isActive = activeItemKey === uniqueKey;

            return (
              <div
                key={uniqueKey}
                ref={(el) => {
                  columnRefs.current[index] = el;
                }}
                className={`flex flex-col shrink-0 mx-1.5 sm:mx-2 md:mx-2.5 transition-all duration-300 ${
                  isActive
                    ? "opacity-100 scale-[1.04] z-10"
                    : "opacity-45 scale-100 grayscale-[20%]"
                }`}
                style={{
                  width: "clamp(104px, 12vw, 132px)",
                  transitionTimingFunction: "cubic-bezier(0.22, 1, 0.36, 1)",
                }}
              >
                {/* Two-Row Image Arrangement */}
                {/* TOP IMAGE */}
                <div className="relative w-full aspect-square overflow-hidden rounded-[5px] bg-neutral-100 shadow-sm">
                  <Image
                    src={item.topImage}
                    alt={`${item.title} Workspace Top`}
                    fill
                    sizes="132px"
                    className="object-cover"
                    loading={index < 12 ? "eager" : "lazy"}
                  />
                </div>

                {/* BOTTOM IMAGE */}
                <div className="relative w-full aspect-square overflow-hidden rounded-[5px] bg-neutral-100 shadow-sm mt-2 sm:mt-2.5">
                  <Image
                    src={item.bottomImage}
                    alt={`${item.title} Workspace Bottom`}
                    fill
                    sizes="132px"
                    className="object-cover"
                    loading={index < 12 ? "eager" : "lazy"}
                  />
                </div>

                {/* LABELS UNDERNEATH */}
                <div className="mt-3 text-left pl-0.5">
                  <span
                    className={`block text-[10px] sm:text-[11px] font-black uppercase tracking-tight leading-tight transition-colors ${
                      isActive ? "text-neutral-950" : "text-neutral-700"
                    }`}
                  >
                    {item.title}
                  </span>
                  <span
                    className={`block text-[9px] sm:text-[10px] leading-snug mt-0.5 font-normal transition-colors ${
                      isActive ? "text-neutral-700 font-medium" : "text-neutral-400"
                    }`}
                  >
                    {item.subtitle}
                  </span>
                </div>
              </div>
            );
          })}
        </motion.div>

        {/* ========================================================= */}
        {/* 2. LAYER: SOFT EDGE FADE OVERLAYS (ABOVE STRIP, BELOW PHONE)*/}
        {/* ========================================================= */}
        {/* LEFT FADE: white -> transparent */}
        <div
          aria-hidden="true"
          className="absolute left-0 top-0 bottom-0 w-24 sm:w-44 md:w-56 bg-gradient-to-r from-white via-white/85 to-transparent pointer-events-none z-20"
        />

        {/* RIGHT FADE: transparent -> white */}
        <div
          aria-hidden="true"
          className="absolute right-0 top-0 bottom-0 w-24 sm:w-44 md:w-56 bg-gradient-to-l from-white via-white/85 to-transparent pointer-events-none z-20"
        />

        {/* Bottom smooth fade to transparent/white */}
        <div
          aria-hidden="true"
          className="absolute inset-x-0 bottom-0 h-16 bg-gradient-to-t from-white via-white/70 to-transparent pointer-events-none z-20"
        />

        {/* ========================================================= */}
        {/* 3. LAYER: CENTRAL PHONE MOCKUP (HIGHEST LAYER OVER STRIP) */}
        {/* ========================================================= */}
        <div
          aria-hidden="true"
          className="absolute left-1/2 -translate-x-1/2 top-1 z-30 pointer-events-none flex justify-center"
          style={{ width: "clamp(170px, 20vw, 218px)" }}
        >
          {/* Phone Frame with realistic shadow and transparent outer corners */}
          <div className="relative w-full aspect-[159/325] drop-shadow-[0_20px_45px_rgba(0,0,0,0.28)]">
            <Image
              src="/assets/slider/phone-mockup.png"
              alt=""
              fill
              priority
              className="object-contain select-none"
            />
          </div>
        </div>
      </div>

      {/* ========================================================= */}
      {/* 4. LAYER: CENTERED BLACK CTA BUTTON                       */}
      {/* ========================================================= */}
      <div className="relative -mt-6 sm:-mt-8 z-35 flex justify-center pb-4">
        <Link
          href="#locations"
          className="inline-flex items-center justify-center bg-black hover:bg-neutral-900 text-white font-semibold px-8 sm:px-10 py-3.5 sm:py-4 rounded-full text-[15px] sm:text-base shadow-xl hover:shadow-2xl active:scale-[0.98] transition-all duration-200 border border-neutral-800"
          style={{ transform: "translateY(0)" }}
        >
          Find Your Perfect Workspace
        </Link>
      </div>
    </div>
  );
}
